import {state,DEMO} from '../../core/state.js?v=9d97c650b6d2';
import {api,boot} from '../../core/api.js?v=9d97c650b6d2';
import {refresh,navigate} from '../../core/events.js?v=9d97c650b6d2';
import {T,esc,icon,heading,btn,field,textarea,formEnd,modal,closeModal,toast,num} from '../../core/ui.js?v=9d97c650b6d2';
export async function load(){}
export function render(){const s=state.workspace;return heading(T('Dự án của tôi','My projects'),T('Chọn dự án để nhập dữ liệu và bắt đầu gán nhãn.','Choose a project to import data and start annotating.'),btn(T('Tạo dự án','New project'),'project:create','primary','plus'))+`<div class="project-library">${s.projects.map(p=>{const current=p.id===s.project?.id;return `<article class="library-card ${current?'current':''}"><div class="between"><span class="library-icon">${icon('folder',24)}</span><span class="badge ${p.archived?'orange':current?'green':'blue'}">${p.archived?T('Lưu trữ','Archived'):current?T('Đang chọn','Selected'):T('Dự án','Project')}</span></div><h2>${esc(p.name)}</h2><p>${esc(p.description||T('Không gian gán nhãn và cộng tác của nhóm.','A collaborative annotation workspace.'))}</p>${current?`<div class="library-stats"><div><b>${num(s.stats.total)}</b><span>${T('Bình luận','Comments')}</span></div><div><b>${num(s.annotation_stats?.annotated_comments||0)}</b><span>${T('Mẫu có nhãn người','Human labelled')}</span></div><div><b>${s.members.length}</b><span>${T('Thành viên','Members')}</span></div></div>`:`<div class="library-other">${icon('lock',14)}${T('Dữ liệu và quyền được tách riêng','Isolated data and access')}</div>`}<div class="library-footer"><span>${p.is_demo?T('Dữ liệu minh họa','Synthetic sample data'):T('Dự án riêng','Private project')}</span>${btn(T('Mở dự án','Open project'),'project:open','link','arrow',`data-id="${p.id}"`)}</div></article>`}).join('')}<button class="library-create" data-action="project:create"><span>${icon('plus',24)}</span><strong>${T('Tạo dự án mới','Create a project')}</strong><p>${T('Bắt đầu với bộ nhãn độc hại<br>hoặc tùy chỉnh theo bài toán.','Start with a toxicity schema<br>or customize your labels.')}</p></button></div>`;}
export async function action(name,el){if(name==='open'){localStorage.setItem('annotaflow.project',el.dataset.id);await boot(Number(el.dataset.id));await refresh('overview');return;}if(name==='create')modal(T('Dự án mới','New project'),`<form data-submit="project:create">${field('name',T('Tên dự án','Project name'),'','text','required maxlength="180"')}${textarea('description',T('Mô tả','Description'))}${formEnd(T('Tạo dự án','Create project'))}</form>`);}
export async function submit(name,f){const v=Object.fromEntries(new FormData(f));const r=await api('projects',v);await boot(r.id);closeModal();await refresh('overview');toast(T('Đã tạo dự án. Bạn có thể chỉnh bộ nhãn trong Cài đặt dự án.','Project created. Customize its schema in Project settings.'));}
